window.OSHA_QUESTIONS_SET5 = [
  { id: "sa-01", category: "sanitation", topic: "Drinking water", q: "On a construction site, potable drinking water must be:", choices: ["Provided, and containers must be clearly marked; a common drinking cup is prohibited", "Optional if there is a gas station nearby", "Shared from one dipper", "Only bottled soda"], a: 0, why: "1926.51(a): potable water, sanitary containers, single-use or sanitary drinking fountain — no common cup." },
  { id: "sa-02", category: "sanitation", topic: "Toilets construction", q: "Construction toilet facilities are generally required at:", choices: ["20 or fewer employees: at least one toilet; then according to the table (e.g., 1 per 40, etc.)", "Only if the job lasts more than a year", "Never on highway work", "One toilet for 500 workers is always enough"], a: 0, why: "1926.51(c): toilets at the jobsite unless employees can use nearby facilities. Number scales with headcount." },
  { id: "sa-03", category: "sanitation", topic: "Washing", q: "Washing facilities are required when:", choices: ["Workers are exposed to harmful contaminants (lead, concrete, chemicals) as specified in sanitation and substance standards", "Never", "Only in offices", "Only after OSHA cites you"], a: 0, why: "1926.51(f) and substance-specific rules (lead, silica, cadmiums): wash so workers do not eat contamination." },
  { id: "sa-04", category: "sanitation", topic: "Eating", q: "Employees shall not eat or drink in areas:", choices: ["Exposed to toxic materials", "That are clean break rooms", "Outdoors in shade with potable water", "With handwashing available and no contamination"], a: 0, why: "1926.51(g) / 1910.141: no food in toilet rooms or areas with toxic exposure. Lead and asbestos add stricter hygiene." },
  { id: "sa-05", category: "sanitation", topic: "Vermin", q: "Every enclosed workplace shall be constructed, equipped, and maintained, so far as reasonably practicable, to prevent:", choices: ["The entrance or harborage of rodents, insects, and other vermin", "All wildlife including birds at any distance", "The use of trash cans", "Natural ventilation"], a: 0, why: "1910.141(a)(5): vermin control. Construction 1926.51 similarly requires cleanliness." },
  { id: "sa-06", category: "sanitation", topic: "GI toilets", q: "In general industry, toilet rooms must be:", choices: ["Provided in accordance with 1910.141 tables, kept clean, and not used for storage of hazardous chemicals as a habit", "Optional over 10 employees", "Shared one stall for 200 as a federal minimum always", "Locked from the outside during the shift"], a: 0, why: "1910.141(c): number of water closets by employee count. Separate rooms for each sex with exceptions for small sites." },
  { id: "sa-07", category: "sanitation", topic: "Nonpotable", q: "Nonpotable water (for firefighting or industrial use) must be:", choices: ["Clearly marked as not for drinking, washing, or cooking", "Used in the cooler if ice is added", "Unlabeled", "The same as potable if it looks clear"], a: 0, why: "1926.51(b): outlets posted. Cross-connections with potable systems are forbidden." },
  { id: "sa-08", category: "sanitation", topic: "Showers", q: "When a standard requires showers (for example certain lead or asbestos work):", choices: ["Employer provides them, soap, and change rooms as specified so street clothes stay clean", "Workers shower at home only as the entire program", "A water bottle is enough", "Garden hose in the parking lot always meets the standard"], a: 0, why: "Substance-specific hygiene facilities prevent take-home exposure to families." },

  { id: "sg-01", category: "signs", topic: "Accident prevention signs", q: "The three OSHA accident-prevention sign classifications are:", choices: ["Danger, Caution, and Safety instruction (plus biological hazard where required)", "Stop, Yield, and Merge", "Red, blue, and brown only as traffic signs", "Exit, Enter, and Wait"], a: 0, why: "1926.200 / 1910.145: Danger (immediate hazard), Caution (potential hazard), Safety instruction. Biohazard for BBP." },
  { id: "sg-02", category: "signs", topic: "Danger sign", q: "A Danger sign is used when:", choices: ["An immediate hazard exists", "A parking reminder is needed", "Only for exits", "The area is safe"], a: 0, why: "Red DANGER signs for immediate danger. Do not overuse them or they lose meaning." },
  { id: "sg-03", category: "signs", topic: "Caution sign", q: "A Caution sign warns of:", choices: ["A potential hazard or unsafe practice", "An immediate kill-zone only", "The lunch menu", "OSHA citations"], a: 0, why: "Yellow CAUTION. Example: wet floor, forklift traffic." },
  { id: "sg-04", category: "signs", topic: "Barricades", q: "Barricades on construction sites must be:", choices: ["Visible and used to warn of hazards (holes, traffic, drop-offs)", "Made of caution tape as the only system for a 20-foot hole", "Optional at night", "The same as a guardrail for fall protection"], a: 0, why: "1926.202 / MUTCD for traffic. Tape is not a guardrail and is not a hole cover." },
  { id: "sg-05", category: "signs", topic: "Flagger", q: "A flagger on a highway job must:", choices: ["Be trained, use proper paddles/flags and high-visibility garments per MUTCD / 1926.201", "Wear dark clothes so they blend in", "Stand in the travel lane with no escape path", "Use a cell phone as the primary signal"], a: 0, why: "1926.201: signaling. High-vis, training, and a safe position. Struck-by is a Focus Four killer in work zones." },
  { id: "sg-06", category: "signs", topic: "Traffic", q: "When construction work affects public traffic, employers must:", choices: ["Use traffic signs, signals, and barricades meeting the MUTCD as required by 1926.200–203", "Rely on workers waving their arms only", "Turn off all lights so drivers slow down", "Leave a single cone at a mile"], a: 0, why: "Subpart G. Night work needs lighting and retroreflective devices." },
  { id: "sg-07", category: "signs", topic: "Exit sign", q: "Exit signs must be:", choices: ["Clearly visible, illuminated as required, and not obstructed or confused with decorations", "The same color as Danger signs always", "Optional in warehouses", "Hidden for security"], a: 0, why: "1910.37(b): each exit must be visible and marked. No furnishings that obscure the path." },
  { id: "sg-08", category: "signs", topic: "Floor load", q: "In buildings, the load rating of floors may need to be:", choices: ["Posted where the standard requires (e.g., 1910.22(d) for certain occupancies)", "Kept secret", "Painted on every 2x4", "Only in the architect’s office"], a: 0, why: "Know storage-area load limits so racks and pallets do not collapse a floor." },

  { id: "vh-01", category: "vehicles", topic: "Construction vehicles", q: "Motor vehicles used on a construction site (off-highway) must have:", choices: ["Working brake lights, audible reverse alarm or equivalent observer, and seats/seat belts as specified in 1926.601", "No lights if used only in daylight always", "A CDL for every pickup on site always", "No inspection ever"], a: 0, why: "1926.601: general construction vehicles. 1926.602 covers earthmoving equipment." },
  { id: "vh-02", category: "vehicles", topic: "Backup alarm", q: "Earthmoving equipment with an obstructed rear view must have:", choices: ["A reverse alarm audible above the surrounding noise, or an observer", "Only a sticker", "No warning if the operator honks sometimes", "A radio playing"], a: 0, why: "1926.602(a)(9): backup alarms. Spotters must be in the operator’s view." },
  { id: "vh-03", category: "vehicles", topic: "Rollover", q: "ROPS (rollover protective structures) are required on many types of:", choices: ["Material-handling and earthmoving equipment listed in 1926.1000–1003 / 1926.602", "All passenger cars", "Office chairs", "Step ladders"], a: 0, why: "Seat belts with ROPS. Do not jump from a tipping machine." },
  { id: "vh-04", category: "vehicles", topic: "Haul roads", q: "Equipment on haul roads should:", choices: ["Be operated within grades, widths, and rules that prevent runaway and collisions; no riders on loads", "Travel any grade without retarding capability", "Carry extra people on the bucket", "Disable backup alarms at night"], a: 0, why: "1926.602: access roads, grades, and no unauthorized riders." },
  { id: "vh-05", category: "vehicles", topic: "Clearance", q: "Before moving a dump truck or trailer, the operator should:", choices: ["Check overhead lines, people, and that the bed/tailgate is clear — raised beds hit power lines", "Raise the bed while driving under lines to dump faster", "Assume the spotter sees everything from the cab", "Text while backing"], a: 0, why: "Raised dump beds are a classic electrocution and overhead-strike pattern." },
  { id: "vh-06", category: "vehicles", topic: "Parking equipment", q: "When parking construction equipment, lower blades/buckets and set the parking brake:", choices: ["Yes — prevent runaway and crush injuries", "Leave the bucket raised as a canopy", "Park on a grade in neutral without chocks", "Leave it running unattended always"], a: 0, why: "Lower implements, chock if needed, and do not leave running equipment as a heater for a nap." },
  { id: "vh-07", category: "vehicles", topic: "Seat belts equipment", q: "Where ROPS is installed, operators must:", choices: ["Wear the seat belt", "Remove the belt so they can jump", "Stand while operating", "Disable the switch"], a: 0, why: "The belt keeps you in the zone of protection. Jumping is how people are crushed." },
  { id: "vh-08", category: "vehicles", topic: "Public roads", q: "When construction vehicles enter public roads they must:", choices: ["Follow traffic laws, be lighted/marked as required, and yield — a backup alarm is not a license to enter blind", "Assume right-of-way always", "Travel in reverse on the highway as standard practice", "Ignore flaggers"], a: 0, why: "Struck-by at site entrances. Use flaggers and truck-entering signs." },
  { id: "vh-09", category: "vehicles", topic: "Crane travel", q: "Traveling a crane with a load or with the boom up:", choices: ["Follow the manufacturer’s travel procedures; many lifts require the load on the hook only when set up, not while roading", "Always travel at highway speed with a long boom", "Needs no spotter for overhead lines", "Is safer than carrying the load on a truck always"], a: 0, why: "Subpart CC travel and assembly/disassembly. Overhead lines and tip-over on grades." },
  { id: "vh-10", category: "vehicles", topic: "Inspect vehicle", q: "At the start of each shift, vehicles in use shall be checked to ensure:", choices: ["That parts, accessories, and equipment affecting safe operation are in proper operating condition", "Only the radio works", "The cup holder is clean", "Nothing — annual shop visits are enough"], a: 0, why: "1926.601(b)(14): shift inspection. Remove defective vehicles from service." },

  { id: "er-01", category: "ergonomics", topic: "No ergonomics standard", q: "OSHA does not currently have a comprehensive ergonomics standard. MSD hazards are addressed by:", choices: ["The General Duty Clause, guidelines, and some industry-specific rules", "A detailed 1910.900 code that cites every lift", "Ignoring back injuries", "Only workers’ comp, never OSHA"], a: 0, why: "Warehouses, nursing, and construction lifting still get General Duty citations when hazards are recognized and feasible controls exist." },
  { id: "er-02", category: "ergonomics", topic: "NIOSH lift", q: "The NIOSH lifting equation recommended weight limit for an ideal lift is about:", choices: ["51 pounds (23 kg) under ideal conditions, reduced by multipliers for reach, frequency, and twist", "100 pounds for everyone", "10 pounds always", "No recommended limit exists"], a: 0, why: "OSHA does not set a 51-lb PEL, but NIOSH RWL is the usual training number. Team lift, mechanical aids, and keep loads close." },
  { id: "er-03", category: "ergonomics", topic: "Safe lift", q: "A safer manual lift generally uses:", choices: ["Load close to the body, stable stance, no twist, and mechanical help when heavy or awkward", "A jerking twist at the waist", "Reaching over a table at arms’ length daily as the method", "Holding your breath and yanking"], a: 0, why: "Construction block, drywall, and rebar are classic MSD sources. Use dollies, forklifts, and two-person lifts." },
  { id: "er-04", category: "ergonomics", topic: "Repetition", q: "Highly repetitive force with poor posture can cause:", choices: ["Sprains, strains, and musculoskeletal disorders (MSDs)", "Only hearing loss", "Cave-ins", "Arc flash"], a: 0, why: "Job rotation, rest breaks, tool handles, and workstation height are administrative/engineering controls." },
  { id: "er-05", category: "ergonomics", topic: "Vibration", q: "Hand-arm vibration from grinders and breakers can cause:", choices: ["Vibration white finger / HAVS — use anti-vibration tools, gloves as adjuncts, and limit trigger time", "Better circulation", "No chronic effect", "Only noise"], a: 0, why: "Low-vibration tools, maintenance, and warm hands. Gloves do not eliminate the need to reduce vibration at the source." },
  { id: "er-06", category: "ergonomics", topic: "Overhead work", q: "Working with hands above the shoulders for long periods:", choices: ["Increases shoulder/neck MSD risk; use lifts, scaffolds at the right height, and job rotation", "Is the healthiest posture", "Only affects the feet", "Is required by OSHA for all trades"], a: 0, why: "Set the work at elbow height when you can. Scissor lifts and baker scaffolds exist for a reason." },
  { id: "er-07", category: "ergonomics", topic: "Push vs pull", q: "When moving carts, it is generally better to:", choices: ["Push than pull, with a load you can control and a clear path", "Pull a stack you cannot see over", "Shove with the lower back bent and twisted", "Ride the cart down a ramp"], a: 0, why: "Pushing uses body weight and lets you see. Keep casters maintained." },
  { id: "er-08", category: "ergonomics", topic: "Early reporting", q: "Workers should report MSD symptoms:", choices: ["Early, so the job can be modified before a recordable strain", "Only after they cannot work", "Never, because of incentives", "Only to social media"], a: 0, why: "Anti-retaliation applies. Early reporting is a program strength, not a failure." },

  { id: "dm-13", category: "demolition", topic: "Floors loaded", q: "Debris shall not be allowed to accumulate to the extent that it:", choices: ["Overloads floors or creates a collapse/fire hazard", "Looks messy only", "Helps brace walls", "Replaces ballast"], a: 0, why: "1926.850 and housekeeping. Know the floor load. Wet debris is heavier." },
  { id: "dm-14", category: "demolition", topic: "Ball crane", q: "The wrecking ball should not be used when:", choices: ["The crane is not designed for balling, or the operator cannot control swing into occupied areas", "The structure is isolated and the crane is rated", "A lift plan exists and the area is cleared", "Tag lines and exclusion zones are in place"], a: 0, why: "1926.859: the ball should not be used when weather or control is inadequate. Never ball a crane not designed for it." },
  { id: "dm-15", category: "demolition", topic: "Walkways demo", q: "Adequate lighting during demolition is required so that:", choices: ["Workers can see holes, drop-offs, and remaining members", "The job looks good on camera only", "Bats stay away", "OSHA night inspections are optional"], a: 0, why: "1926.850(n) and 1926.26: illumination. Demo sites are full of unmarked holes." },
  { id: "dm-16", category: "demolition", topic: "Employee entry", q: "Only employees necessary to the demolition shall be permitted in the area when:", choices: ["Walls or members are being pulled or dropped", "Lunch is served", "The survey is being written off-site", "Utilities are already dead and the building is a parking lot"], a: 0, why: "Keep spectators and extra trades out of the collapse radius." },
  { id: "dm-17", category: "demolition", topic: "Masonry walls demo", q: "Masonry walls shall not be permitted to fall on floors of a building in such masses as to exceed:", choices: ["The safe carrying capacity of the floor", "One brick", "The weight of the crane", "A pickup truck always"], a: 0, why: "1926.854: floor capacity. Sequential demo." },
  { id: "dm-18", category: "demolition", topic: "Standpipe", q: "During demo of a building with a standpipe, fire protection may need to be:", choices: ["Maintained as required by the fire code / 1926.850 as applicable until it becomes a hazard itself", "Removed first always", "Used to flood every floor for dust only", "Ignored"], a: 0, why: "Coordinate with the fire department. Hot work plus demo debris is a fire load." },

  { id: "tl-13", category: "tools", topic: "Switches", q: "Circular saws, chain saws, and percussion tools must have:", choices: ["A constant-pressure switch that shuts off when released (with specified exceptions)", "A lock-on trigger as the only allowed control for circular saws", "No switch so they run continuously", "A switch that sticks on for convenience"], a: 0, why: "1926.300(d) / 1910.243: on-off controls. Many circular saws may not have a lock-on." },
  { id: "tl-14", category: "tools", topic: "Chain saw", q: "Chain-saw users should:", choices: ["Know kickback zones, keep both hands on the saw, and wear chaps/eye/ear/head protection as required", "Cut with the tip of the bar as the normal method", "Hold the saw one-handed overhead", "Disable the chain brake"], a: 0, why: "Kickback kills. Construction wood and demo saws still kick. PPE plus technique." },
  { id: "tl-15", category: "tools", topic: "Powder shielding", q: "When firing a powder-actuated tool, the operator must:", choices: ["Have the tool perpendicular and the shield in place; do not fire into spalling or extra-hard/soft material contrary to instructions", "Fire around corners", "Use it as a hammer on misfires immediately", "Leave it loaded on a scaffold"], a: 0, why: "1926.302(e): inspecting the tool twice daily, and not firing into materials that could allow the fastener to pass through into an occupied area." },
  { id: "tl-16", category: "tools", topic: "Electric tools ground", q: "A three-wire tool with a missing ground pin must be:", choices: ["Taken out of service", "Used with a cheater adapter", "Taped and returned to service", "Used only outdoors"], a: 0, why: "The ground path is gone. Double-insulated two-wire tools are different — look for the box-in-box mark." },
  { id: "tl-17", category: "tools", topic: "Hydraulic jacks block", q: "After a jack lifts a load, you should:", choices: ["Crib or block the load; do not rely on the jack as the sole support while working under it", "Crawl under with the jack as the only support", "Kick the jack out", "Exceed the rated capacity if the load is almost up"], a: 0, why: "1926.305: blocking. Jacks leak down." },
  { id: "tl-18", category: "tools", topic: "Nail gun", q: "Pneumatic nailers should:", choices: ["Be disconnected when unattended; never pointed at people; sequential triggers reduce bump-fire injuries", "Be carried with a finger on the trigger as standard", "Be used to hang tools on a coworker’s clothing", "Have the hose whip freely without retainers"], a: 0, why: "Work-contact and sequential trip modes. Eye protection. OSHA and NIOSH have nail-gun guidance." },
  { id: "tl-19", category: "tools", topic: "Abrasive cutoff", q: "Abrasive cutoff wheels on a chop saw:", choices: ["Need the guard; do not grind on the side of a wheel not rated for it; let the wheel stop before setting the saw down", "Should have the guard removed for a full view", "Can be side-loaded like a grinding disc always", "Need no RPM match"], a: 0, why: "Wheel bursts send fragments at high speed. Ring-test and RPM match still apply." },
  { id: "tl-20", category: "tools", topic: "Hand saw condition", q: "A hand saw with a dull, bent, or unsecured blade:", choices: ["Is more likely to bind and cut the user — repair or replace", "Is safer because it is slow", "Meets OSHA as-is", "Should be used without a handle for control"], a: 0, why: "1926.301: handles on files and tools. Sharp tools are safer than dull ones that slip." },

  { id: "fa-11", category: "firstaid", topic: "Near proximity", q: "OSHA has described “near proximity” for medical care in some interpretations as:", choices: ["About 3–4 minutes for life-threatening, and up to 15 minutes for non-life-threatening in some letters — still have trained first aid if you cannot rely on that", "2 hours is always fine", "Only 911 with no supplies ever", "A clinic in the next county always counts"], a: 0, why: "Remote construction and logging need on-site first aid. Do not assume an ambulance will beat a mill-yard bleed." },
  { id: "fa-12", category: "firstaid", topic: "Posted numbers", q: "Telephone numbers of physicians, hospitals, and ambulances should be:", choices: ["Conspicuously posted where 1926.50 requires", "Only in the superintendent’s head", "On a phone that is dead", "Optional on highway jobs"], a: 0, why: "1926.50(f): posting. Cell coverage is not guaranteed — have a plan." },
  { id: "fa-13", category: "firstaid", topic: "Stretchers", q: "On sites where stretchers are required by the nature of the work, they should be:", choices: ["Available and the crew should know how to use them without making a spinal injury worse", "Used as scaffolding", "Left at the shop", "Improvised from rebar always"], a: 0, why: "1926.50(d) appendix and remote-work practice. Train before you need it." },
  { id: "fa-14", category: "firstaid", topic: "Burns thermal", q: "For thermal burns, first aid generally includes:", choices: ["Cool with water, cover loosely, do not break blisters, seek medical care for serious burns", "Butter and ice directly on open burns as the preferred method", "Cotton soaked in solvent", "Ignoring electrical burns because the skin looks OK"], a: 0, why: "Electrical and chemical burns need extra care. When in doubt, EMS." },
  { id: "fa-15", category: "firstaid", topic: "CPR AED", q: "After a workplace cardiac arrest, survival improves with:", choices: ["Early 911, CPR, and AED shock if indicated", "Waiting to see if they wake up in 20 minutes", "Walking them around", "Giving water only"], a: 0, why: "Minutes matter. Include AEDs in the EAP if you have them and train." },

  { id: "sw-11", category: "stairways", topic: "Handrail grasp", q: "A stair handrail must be:", choices: ["Graspable, between about 30 and 37 inches from the tread, and able to withstand specified force", "A 2x4 laid flat as the preferred graspable rail always", "Optional if workers are young", "60 inches high like a guardrail top"], a: 0, why: "1926.1052(c): height, clearance from walls, and 200 lb force similar to guardrails in some respects. Smooth surface." },
  { id: "sw-12", category: "stairways", topic: "Unprotected sides", q: "Unprotected sides and edges of stairway landings shall be:", choices: ["Provided with a guardrail system", "Marked with chalk", "Left open for material staging", "Protected with caution tape only"], a: 0, why: "1926.1052(c)(12): landing edges. Subpart M guardrail specs." },
  { id: "sw-13", category: "stairways", topic: "Doors on landings", q: "Doors opening onto a stairway landing must not:", choices: ["Reduce the effective landing width below the required minimum when the door is open", "Exist", "Have panic hardware", "Swing at all"], a: 0, why: "1926.1052(a)(4): landing must remain large enough with the door open." },
  { id: "sw-14", category: "stairways", topic: "Metal pan temporary", q: "Until pans are filled, workers using metal-pan stairs need:", choices: ["Temporary fill (wood or other) so the pan is not an open trap", "To walk the stringers only", "No extra measures", "To jump from pan to pan"], a: 0, why: "Empty pans are a classic broken-leg hazard." },
  { id: "sw-15", category: "stairways", topic: "Lighting stairs", q: "Stairways in use shall be:", choices: ["Lighted so workers can see treads and hazards", "Dark to save energy", "Used to store formwork", "Iced for traction"], a: 0, why: "1926.56 illumination tables plus housekeeping. Construction stairs are a frequent fall location." },

  { id: "ww-16", category: "walking", topic: "1910.22 general", q: "Walking-working surfaces in GI must be inspected:", choices: ["Regularly and as needed, and hazardous conditions corrected or guarded", "Never", "Only after a fatality", "Once when the building is new"], a: 0, why: "1910.22(d): inspect. Covers, guardrails, and housekeeping are day-to-day duties." },
  { id: "ww-17", category: "walking", topic: "Ladder GI 24 ft", q: "A fixed ladder in general industry that extends more than 24 feet above a lower level generally needs:", choices: ["A personal fall arrest system or ladder safety system (cages are being phased out as the primary means)", "Only paint", "A rope", "Nothing if used by contractors"], a: 0, why: "1910.28(b)(9): phase-in dates. New ladders cannot rely on cages alone." },
  { id: "ww-18", category: "walking", topic: "Rope descent building owner", q: "Before allowing rope descent, the building owner must:", choices: ["Provide written information that anchorages have been identified, tested, certified, and maintained", "Do nothing — it is only the contractor’s problem", "Ban window washing", "Provide a single untested pipe"], a: 0, why: "1910.27(b): building owner duties. Contractors still inspect their own RDS gear." },
  { id: "ww-19", category: "walking", topic: "Scaffolds GI", q: "Scaffolds in general industry (non-construction) generally follow:", choices: ["1910 Subpart D walking-working plus manufacturer rules; many employers still use 1926 Subpart L practices", "No rules", "Only fire codes", "1926 Subpart P trenches"], a: 0, why: "1910.27–28 address some scaffold/ladder issues. Construction scaffolds remain 1926.451 when it is construction work." },
  { id: "ww-20", category: "walking", topic: "Falling objects GI", q: "When there is a falling-object hazard, GI employers must:", choices: ["Protect workers with toeboards, screens, canopy, or barricades as specified in 1910.28", "Rely only on hard hats always as the complete system", "Yell “look out” as the engineering control", "Remove all toeboards for cleanliness"], a: 0, why: "Hard hats are PPE, last in the hierarchy. Keep people out of the drop zone." },

  { id: "st-16", category: "steel", topic: "Deck attachments", q: "Metal decking shall be laid tightly and immediately secured to prevent:", choices: ["Accidental displacement and as a working surface so far as practicable", "All welding", "Use of fall protection", "Tag lines"], a: 0, why: "1926.754(e): decking. Do not leave loose sheets as a sail in the wind." },
  { id: "st-17", category: "steel", topic: "Roof hole steel", q: "Holes in metal deck during steel erection must be:", choices: ["Protected by covers, guardrails, or equivalent — including skylight openings", "Left open for HVAC later with no mark", "Covered with insulation only", "Ignored under 15 feet"], a: 0, why: "Same hole rules plus Subpart R. Skylights kill ironworkers and roofers." },
  { id: "st-18", category: "steel", topic: "Joist erection", q: "A steel joist shall not be placed on any support unless the support is:", choices: ["Stabilized — do not use unbridged joists as a walkway", "Still on the truck", "Temporary wood of any size", "A stack of decking"], a: 0, why: "1926.757: joists. Erection bridging, and fall protection. Joists roll and dump workers." },
  { id: "st-19", category: "steel", topic: "Column splice", q: "When making a column splice, workers need:", choices: ["Adequate access and fall protection; the member must be stable", "To stand on the flange without PFAS at 40 feet as the preferred method", "No bolts if they hold it by hand", "A forklift as the only crane"], a: 0, why: "Connectors still have height triggers. Stability of the piece is the erector’s job with the crane." },
  { id: "st-20", category: "steel", topic: "Double connections", q: "At beam-to-column double connections where the beam has not been field-bolted, a seat, lifting device, or equivalent is needed so that:", choices: ["The first beam cannot drop when the shared bolts are removed for the second member", "The crane can leave immediately", "No fall protection is used", "Decking can be skipped"], a: 0, why: "1926.756(c): double connections. A known collapse/fall pattern." },

  { id: "cn-16", category: "concrete", topic: "Lift-slab", q: "Lift-slab operations have extra requirements including:", choices: ["A PE, synchronized lifting, and no employees under the slab during jacking except those essential and protected as specified", "Workers standing under the slab to watch jacks", "No drawings", "Manual chain hoists only"], a: 0, why: "1926.705: lift-slab. Several historic collapses. Stay out from under." },
  { id: "cn-17", category: "concrete", topic: "Precast bracing", q: "Until permanent connections are complete, precast walls must be:", choices: ["Braced to prevent collapse from wind or impact", "Free-standing if they look heavy", "Held by a laborer", "Leaned on lumber scraps"], a: 0, why: "1926.704: erection drawings. Wind on a wall panel is a sail." },
  { id: "cn-18", category: "concrete", topic: "Rebar caps", q: "Impalement protection on vertical rebar must be:", choices: ["Capable of withstanding the impact of a fall — tested/listed caps or troughs, not decorative mushrooms that fail", "Any plastic cap", "Paint", "Optional below 6 feet always even if you can fall onto the steel"], a: 0, why: "OSHA has emphasized that some “mushroom” caps do not protect. Use systems that work. Fall protection still applies at 6 feet on formwork/rebar." },
  { id: "cn-19", category: "concrete", topic: "Shoring inspection", q: "A designated qualified designer or a designated qualified inspector (as specified) must inspect shoring:", choices: ["Immediately prior to, during, and immediately after concrete placement", "Once at the start of the project only", "Never if the carpenter is experienced", "After the pour hardens only"], a: 0, why: "1926.703(b): inspections. Overloading and missing braces cause disasters." },
  { id: "cn-20", category: "concrete", topic: "Masonry wind", q: "During masonry construction, wind can:", choices: ["Blow over unbraced walls — follow bracing and LAZ rules even if the wall is only a few days old", "Only affect steel", "Never affect CMU", "Be ignored under 20 mph always"], a: 0, why: "1926.706: limited access zone and bracing over 8 feet. Green masonry has little tensile strength." },

  { id: "ae-16", category: "aerial", topic: "Indoor vs outdoor", q: "Some scissor lifts are rated indoor-only because:", choices: ["Wind load and wheel/surface ratings differ — using an indoor machine outside can tip it", "OSHA bans all outdoor lifts", "Batteries only work indoors", "Guardrails are shorter outdoors"], a: 0, why: "Read the decal. Outdoor rating includes wind. Indoor machines on a parking lot in a gust have killed people." },
  { id: "ae-17", category: "aerial", topic: "Gate chain", q: "The platform gate or chain on a lift must be:", choices: ["Closed when the platform is elevated", "Left open for easy access at height", "Used as a step", "Removed if it rattles"], a: 0, why: "1926.453 and manufacturer: occupancy with the entrance closed. Do not climb out onto a roof without a plan and anchorage." },
  { id: "ae-18", category: "aerial", topic: "Ground person", q: "A person on the ground should know:", choices: ["How to use ground controls / emergency lowering if the operator is incapacitated", "Nothing — it is not their lift", "Only how to take photos", "How to drive the lift while people are on the rails"], a: 0, why: "Rescue plan. Keys, e-stop, and lowering valves. Do not leave an elevated worker alone without a way down." },
  { id: "ae-19", category: "aerial", topic: "Insulated boom myth", q: "An “insulated” boom on a contractor’s rental lift:", choices: ["Does not make it safe to work next to distribution lines unless you are a qualified line-clearance crew using a tested unit within its rating", "Means OSHA 10 holders can contact primary lines", "Needs no dielectric testing ever", "Replaces the 10-foot rule for everyone"], a: 0, why: "Most construction boom lifts are not maintained as insulated aerial devices. Stay away from lines." },
  { id: "ae-20", category: "aerial", topic: "Load chart boom", q: "As a boom extends or the basket goes up and out, capacity typically:", choices: ["Decreases — check the chart at that geometry", "Increases", "Stays the same as stowed", "Doubles with two workers"], a: 0, why: "Moment arm. Two workers plus a bundle of pipe at full reach is a tip-over waiting to happen." },

  { id: "cs-26", category: "confined", topic: "Construction host", q: "On a construction site, the controlling contractor must:", choices: ["Share information about permit spaces and coordinate with other contractors under Subpart AA", "Stay silent about pits and tanks", "Only the host in general industry has duties, never construction", "Post a sign and do nothing else"], a: 0, why: "1926.1203: coordinating, informing, and debriefing. Multiple employers create gaps." },
  { id: "cs-27", category: "confined", topic: "Continuous monitor", q: "During permit entry, the atmosphere shall be tested:", choices: ["As specified on the permit — often continuously or frequently enough to warn of changes", "Once the week before", "Never if it smelled OK", "Only for oxygen if the space is a tank that held chemicals"], a: 0, why: "Stratification: test at multiple levels. Meters in the breathing zone of the entrant when possible." },
  { id: "cs-28", category: "confined", topic: "Inerting", q: "Inerting a space with nitrogen:", choices: ["Creates an oxygen-deficient IDLH atmosphere — treat it as immediately dangerous", "Makes the space safe to enter without a respirator", "Is the same as ventilation with fresh air", "Raises oxygen above 23.5%"], a: 0, why: "Inerting prevents fire by removing oxygen. It will asphyxiate you. SCBA/SAR and permits." },
  { id: "cs-29", category: "confined", topic: "Cancel permit", q: "The entry supervisor must cancel the permit when:", choices: ["Operations are complete or a condition not allowed by the permit arises", "The attendant takes a lunch inside the space", "A week has passed even if people are still inside", "The meter was never used"], a: 0, why: "1910.146(e)(5): terminate and close the permit. Re-issue after re-evaluation if work continues." },
  { id: "cs-30", category: "confined", topic: "Unauthorized", q: "If unauthorized persons approach a permit space, the attendant must:", choices: ["Warn them to stay away and notify the supervisor as needed", "Invite them in to help", "Leave the post to chase them across the plant", "Ignore them"], a: 0, why: "1910.146(i): attendant duties include keeping unauthorized persons out." },

  { id: "hz-26", category: "hazwoper", topic: "Specialist", q: "A hazardous materials specialist:", choices: ["Supports technicians with more specific knowledge of the substances and the state plan, with training at least equivalent to technician plus extra competencies", "Is the same as awareness", "Never enters the warm zone", "Needs no PPE knowledge"], a: 0, why: "1910.120(q)(6)(iv): specialist. Often a chemist or industry expert role at the scene." },
  { id: "hz-27", category: "hazwoper", topic: "Skilled support", q: "Skilled support personnel (e.g., a crane operator called to an emergency):", choices: ["Receive an on-site briefing of hazards, PPE, and duties before they participate", "Need the full 40-hour course before they can pick a wrecked tank", "Need no information", "Replace the IC"], a: 0, why: "1910.120(q)(4): briefing. Do not send an unbriefed operator into a plume." },
  { id: "hz-28", category: "hazwoper", topic: "Specialist employee", q: "Employees who work with hazardous substances only occasionally in their regular jobs and may be called to a scene:", choices: ["Need training on the hazards of those substances and the emergency plan (specialist employee)", "Are exempt from all HAZWOPER", "Must be technicians in every case", "Only need OSHA 10"], a: 0, why: "1910.120(q)(5): specialist employees. Annual demonstration of competency." },
  { id: "hz-29", category: "hazwoper", topic: "Table 2 PPE", q: "HAZWOPER PPE selection uses:", choices: ["Site characterization and 1910.120(g) / Appendix B levels — not guessing Level D in an unknown pit", "The cheapest tyvek always", "Cotton coveralls for IDLH", "No gloves if you wash later"], a: 0, why: "Unknown atmospheres are treated as IDLH until characterized. Upgrade/downgrade with data." },
  { id: "hz-30", category: "hazwoper", topic: "Illumination cleanup", q: "Hazardous-waste cleanup operations need lighting of at least:", choices: ["Specified foot-candles in 1910.120 Table H-120.1 (e.g., 5 fc general, more for shops and first aid)", "Candlelight only", "No lighting standard", "Only headlights on trucks"], a: 0, why: "People trip in the dark with air lines and pits. Meet the table." },

  { id: "bb-16", category: "bloodborne", topic: "Exposure determination", q: "The exposure determination in the ECP lists:", choices: ["Jobs and tasks where occupational exposure occurs, without regard to PPE", "Only names of HIV-positive clients", "Lunch duties", "Office staff with no first-aid role always"], a: 0, why: "1910.1030(c)(2): job classification lists. PPE is not an excuse to skip the determination." },
  { id: "bb-17", category: "bloodborne", topic: "Work practices", q: "Which is a required work practice?", choices: ["No recapping of needles by two-handed technique; no eating in contaminated areas; minimize splashing", "Bend needles by hand before disposal", "Mouth pipetting of blood", "Open-toed shoes in the lab as PPE"], a: 0, why: "1910.1030(d)(2): work practices. Engineering controls first." },
  { id: "bb-18", category: "bloodborne", topic: "Laundry", q: "Contaminated laundry shall be:", choices: ["Handled as little as possible, bagged in labeled/color-coded bags, and not sorted in the location of use if it would expose others", "Taken home by the worker to wash with family clothes as the preferred method", "Shaken to remove clots", "Washed with street clothes in the break-room machine"], a: 0, why: "1910.1030(d)(4)(iv): laundry. Take-home contamination is a family hazard." },
  { id: "bb-19", category: "bloodborne", topic: "Declination", q: "If a worker declines the hepatitis B vaccine they must:", choices: ["Sign the mandatory declination form; they can still receive the vaccine later at no cost if they remain at risk", "Be fired", "Pay for the vaccine themselves later always", "Never be offered again"], a: 0, why: "Appendix A declination language is mandatory. Keep the form." },
  { id: "bb-20", category: "bloodborne", topic: "Sharps log", q: "Employers with occupational exposure (except in certain states/exceptions) maintain a sharps injury log of:", choices: ["Percutaneous injuries from contaminated sharps, with type/brand, area, and explanation of how it happened — privacy protected", "All paper cuts", "Only lawsuits", "Supervisor opinions with names posted"], a: 0, why: "1910.1030(h)(5): sharps log. Used to evaluate safer devices." },

  { id: "rp-16", category: "respiratory", topic: "Program admin", q: "The respiratory program must have:", choices: ["A qualified program administrator who administers the written program", "No single person in charge", "Only a vendor", "OSHA as the on-site administrator"], a: 0, why: "1910.134(c)(3): administrator. They need enough knowledge to run medical, fit, and cartridge decisions." },
  { id: "rp-17", category: "respiratory", topic: "IDLH unknown", q: "If the employer cannot identify or reasonably estimate exposure, the atmosphere shall be considered:", choices: ["IDLH", "Immediately safe", "Nuisance dust only", "Oxygen enriched"], a: 0, why: "1910.134(d)(1)(iii): unknown = IDLH. That drives SCBA/SAR until you have data." },
  { id: "rp-18", category: "respiratory", topic: "Interior structural firefighting", q: "Interior structural firefighting requires:", choices: ["SCBA, buddy system, and two-in/two-out as specified in 1910.134(g)(4)", "Dust masks", "Lone firefighter entries as the standard", "APRs for smoke"], a: 0, why: "Two-in/two-out. Fire brigades also have 1910.156." },
  { id: "rp-19", category: "respiratory", topic: "Canister vs cartridge", q: "A canister APF and duration vs a cartridge:", choices: ["Canisters are typically larger and used on gas masks; still not for IDLH unless the device is designed and NIOSH-approved for that use", "Canisters always allow IDLH entry without SCBA", "Cartridges supply oxygen", "They are identical in every approval"], a: 0, why: "Read the NIOSH approval. Escape-only devices are not entry devices." },
  { id: "rp-20", category: "respiratory", topic: "Cleaning", q: "Shared respirators must be:", choices: ["Cleaned and disinfected as often as necessary so they do not harm the wearer; after each use if used by different people", "Passed around dirty", "Washed in gasoline", "Never inspected"], a: 0, why: "1910.134(h) and Appendix B-2: cleaning procedures." },

  { id: "mg-16", category: "machineguard", topic: "1910.219", q: "Gears, sprockets, and belts must be:", choices: ["Guarded if they are 7 feet or less from the floor or working platform as specified", "Left open for oiling while running as the preferred method", "Painted yellow instead of guarded", "Guarded only above 7 feet always and never below"], a: 0, why: "1910.219: mechanical power-transmission apparatus. Oiling while guarded/running has strict conditions." },
  { id: "mg-17", category: "machineguard", topic: "Radial saw", q: "A radial-arm saw used for ripping must have:", choices: ["The spreader, anti-kickback fingers, and the saw must return to the start position — and not be able to go past the table edge in some setups", "No spreader", "The blade unguarded", "A dado without any control"], a: 0, why: "1910.213(h) / (s): radial saws. Kickback and the saw walking out at the operator." },
  { id: "mg-18", category: "machineguard", topic: "Portable circular", q: "Portable circular saws shall be equipped with:", choices: ["Guards above and below the base plate; the lower guard retracts and returns automatically", "No lower guard", "A wedge holding the guard open", "Metal blades unguarded for masonry only as a habit"], a: 0, why: "1910.243(a)(1). Same idea in construction 1926.304." },
  { id: "mg-19", category: "machineguard", topic: "Lockout servicing", q: "Changing a saw blade or clearing a jam generally requires:", choices: ["Energy isolation / LOTO, not reaching into a live blade", "A stick while the saw coasts as the only method always", "No protection if you are careful", "Bypassing the cover interlock"], a: 0, why: "Servicing vs production. Unplug small tools and keep the plug in your control, or lock the disconnect." },
  { id: "mg-20", category: "machineguard", topic: "Robotics", q: "Industrial robots require:", choices: ["Guarding, presence sensing, or interlocked cells so workers are not in the swing radius; lockout for entry into the cell", "Workers standing in the cell during automatic operation as standard", "No standard of care", "Only a painted line"], a: 0, why: "1910.212 plus ANSI/RIA R15.06 practice. Teach-mode has reduced-speed rules. Fatalities happen in cells." },

  { id: "ps-16", category: "psm", topic: "Appendix A chlorine", q: "Chlorine’s PSM threshold quantity in Appendix A is:", choices: ["1,500 pounds", "10,000 pounds", "100 pounds", "1 pound"], a: 0, why: "1910.119 App A: chlorine 1,500 lb. A 1-ton cylinder is already over TQ if in one process." },
  { id: "ps-17", category: "psm", topic: "Ammonia TQ", q: "Anhydrous ammonia’s listed TQ is:", choices: ["10,000 pounds", "1,500 pounds", "500 pounds", "100,000 pounds"], a: 0, why: "App A: ammonia 10,000 lb. Refrigeration systems can easily exceed this." },
  { id: "ps-18", category: "psm", topic: "Retail exemption", q: "Flammable liquids used solely as fuel for workplace consumption of those fuels (e.g., heating) may be:", choices: ["Exempt from PSM under 1910.119(a)(1)(ii) exceptions as specified", "Always covered at 10 gallons", "Covered only if diesel", "Exempt from all of OSHA"], a: 0, why: "The hydrocarbon-fuels exemption is narrow. A process that uses flammables as a feedstock is not “workplace consumption as fuel.”" },
  { id: "ps-19", category: "psm", topic: "Contractor injury log", q: "The host must maintain a log of:", choices: ["Contract employees’ injuries/illnesses related to work in process areas, separate from or identified within recordkeeping as specified", "Only host employees, never contractors", "Near misses only", "OSHA 300A for the city"], a: 0, why: "1910.119(h)(2)(vi): contractor injury/illness log related to the contractor’s work in process areas." },
  { id: "ps-20", category: "psm", topic: "RAGAGEP", q: "Recognized and Generally Accepted Good Engineering Practices (RAGAGEP) are used in PSM for:", choices: ["Equipment design, inspection, and mechanical integrity", "Cafeteria menus", "Hard-hat stickers only", "Ignoring codes"], a: 0, why: "1910.119(d)(3)(ii) and (j): follow RAGAGEP or document equally protective alternatives." },

  { id: "wd-21", category: "welding", topic: "Cylinder distance", q: "Oxygen cylinders in storage must be separated from fuel-gas cylinders by 20 feet or a 5-foot fire wall. When in use on a cart:", choices: ["They may be together on a designed cart with the regulators on, under the standard’s in-use rules — still keep oil away from oxygen", "They may be stored overnight with regulators on in a closed trailer as the preferred storage", "Caps may stay off in the gang box for weeks", "Acetylene may be laid on its side for days then used immediately at 30 psig"], a: 0, why: "1926.350: in-use vs storage. If they will sit, treat as storage: cap, separate, secure." },
  { id: "wd-22", category: "welding", topic: "Manifold", q: "Fuel-gas manifolds must be:", choices: ["Located and installed per the standard — listed equipment, proper ventilation, and no mixing of oxygen and fuel in one manifold", "Built from plumbing tees in the shop", "Placed next to oil drums", "Used to increase acetylene above 15 psig"], a: 0, why: "1926.350(e) and 1910.253: manifolding. Acetylene still has the 15 psig rule." },
  { id: "wd-23", category: "welding", topic: "Arc flash welding", q: "Helpers watching the arc without a lens can get:", choices: ["Photokeratitis (“welder’s flash”) hours later — screens and filter lenses for anyone who can see the arc", "A tan only", "No eye effect", "Better night vision"], a: 0, why: "UV burns the cornea. Screens, curtains, and warning signs." },
  { id: "wd-24", category: "welding", topic: "Local exhaust", q: "Local exhaust for welding is placed:", choices: ["As close as practicable to the plume so contaminants are captured before the breathing zone", "Behind the welder to blow fume into their face", "At the far end of the shop only", "Using oxygen as the make-up air"], a: 0, why: "1926.353: capture velocity at the source. Do not oxygen-ventilate." },
  { id: "wd-25", category: "welding", topic: "Fire watch persons", q: "A fire watcher is required when:", choices: ["Combustibles are closer than 35 feet and cannot be moved/protected, or other 1910.252 conditions (wall openings, etc.)", "You weld over a dirt field with nothing combustible within 100 feet and no openings", "Always in every parking lot", "Never if you have an OSHA 10 card"], a: 0, why: "1910.252(a)(2)(iii): conditions that trigger a fire watch. At least 30 minutes after." },

  { id: "fk-31", category: "forklift", topic: "Railroad tracks", q: "When crossing railroad tracks with a forklift, the operator should generally:", choices: ["Cross diagonally so not both wheels drop at once, at a slow speed", "Straddle the rail at high speed", "Raise the load to the max", "Stop on the tracks to check the phone"], a: 0, why: "1910.178(n)(7): diagonal crossing. Never park on tracks." },
  { id: "fk-32", category: "forklift", topic: "Grades loaded", q: "On grades, loaded trucks should be driven with the load:", choices: ["Upgrade (uphill), forks tilted back, and no turning on the ramp if avoidable", "Downhill with the load leading always", "Sideways", "Raised high for visibility"], a: 0, why: "1910.178(n)(7)(i): load upgrade. Keep the CG stable." },
  { id: "fk-33", category: "forklift", topic: "Dock plates", q: "Portable dockboards shall be:", choices: ["Secured in place, with handholds or other effective means to handle them, and designed to prevent vehicles from running off the edge as specified", "A loose plate of unknown capacity", "Used even if the trailer has pulled away 2 feet", "Made of plywood for 10,000-lb trucks"], a: 0, why: "1910.178(k) / 1910.30: dockboards. Trailer creeps — use restraints." },
  { id: "fk-34", category: "forklift", topic: "Order picker", q: "An order-picker lift that elevates the operator typically requires:", choices: ["Fall protection / operator restraint as the manufacturer and 1910.178 training require, plus gate closed", "Standing on the forks of a counterbalanced truck instead", "No training beyond a car license", "Travel at high speed elevated in the aisle always"], a: 0, why: "Different truck class. Harness tethers on many order pickers. Do not mix training from a sit-down truck." },
  { id: "fk-35", category: "forklift", topic: "Pedestrian no-zones", q: "A raised load is:", choices: ["A no-go zone for pedestrians — never walk under forks", "A good rain shelter", "Safe if the operator sees you", "Allowed if you tap the mast"], a: 0, why: "1910.178(m)(2): no person under the load. Hydraulic failure drops the forks." },

  { id: "lo-26", category: "loto", topic: "Exception cord", q: "The cord-and-plug exception applies only when:", choices: ["Unplugging fully de-energizes AND the plug is under the exclusive control of the employee doing the work", "The tool is 480-volt hard-wired", "Two people share the unplugged cord across the room", "A helper might plug it back in"], a: 0, why: "If you walk to the tool crib, someone can plug it in. Take the plug with you or lock it." },
  { id: "lo-27", category: "loto", topic: "Tags meaning", q: "A tag on a disconnect means:", choices: ["Do not operate — it is a warning, not a physical restraint; lockout is required when the device can accept a lock", "The machine is safe to start", "It replaces verification", "Anyone may remove it to run production"], a: 0, why: "Tags can be ignored or fall off. Locks hold the energy isolating device." },
  { id: "lo-28", category: "loto", topic: "Stored mechanical", q: "A raised dump bed, press ram, or spring must be:", choices: ["Blocked or released so gravity/spring energy cannot move during servicing", "Ignored if the motor is locked out", "Held by a coworker", "Trusted to hydraulic check valves only without evaluation"], a: 0, why: "1910.147(d)(5): stored energy. Cribbing, pins, and dissipation." },
  { id: "lo-29", category: "loto", topic: "Affected training", q: "Affected employees must be trained on:", choices: ["The purpose of LOTO and not to start equipment that is locked/tagged", "How to cut locks", "Machine-specific isolation of every valve", "Nothing"], a: 0, why: "1910.147(c)(7)(ii): awareness so they do not defeat the system." },
  { id: "lo-30", category: "loto", topic: "Periodic inspection documented", q: "The annual LOTO inspection must be:", choices: ["Certified (documented) that the procedure was inspected and who inspected it", "Verbal only", "Optional if no injuries", "Done by an affected employee only without authorized involvement"], a: 0, why: "1910.147(c)(6)(ii): certification. Review with authorized employees of deviations." },

  { id: "hc-26", category: "hazcom", topic: "SDS access time", q: "SDS must be:", choices: ["Readily accessible during each work shift to employees when they are in their work area", "Locked in a headquarters office two hours away with no after-hours access", "Available only to supervisors", "Posted as a 1-page summary that replaces SDS always"], a: 0, why: "1910.1200(g)(8): no barriers to access. Electronic systems need a backup if the network is down." },
  { id: "hc-27", category: "hazcom", topic: "Pictogram skull", q: "The skull-and-crossbones pictogram indicates:", choices: ["Acute toxicity (fatal or toxic)", "An oxidizer", "A compressed gas", "An irritant only"], a: 0, why: "GHS acute toxicity Categories 1–3 typically. The exclamation mark covers “harmful” (Category 4)." },
  { id: "hc-28", category: "hazcom", topic: "Gas cylinder pictogram", q: "The gas-cylinder pictogram means:", choices: ["Gases under pressure", "Explosives", "Flammable solids only", "Aquatic toxicity"], a: 0, why: "Burst, cold, or asphyxiation hazards from cylinders. Store and cap properly." },
  { id: "hc-29", category: "hazcom", topic: "Corrosion pictogram", q: "The corrosion pictogram covers:", choices: ["Skin corrosion, serious eye damage, and corrosion to metals", "Only rust on tools", "Carcinogens", "Oxidizers"], a: 0, why: "Acids/bases. Use the right gloves and eyewash. Do not mix bleach and acid." },
  { id: "hc-30", category: "hazcom", topic: "Written program access", q: "The written HazCom program must be:", choices: ["Available to employees, their representatives, and OSHA", "A trade secret from workers", "Optional under 25 employees always", "Replaced by SDS alone with no program"], a: 0, why: "1910.1200(e): written program. List of chemicals, labels, SDS, and training described." },

  { id: "pp-31", category: "ppe", topic: "Payment replacement", q: "When PPE is worn out from work use, the employer:", choices: ["Pays to replace it (except the listed payment exceptions such as non-specialty safety-toe shoes in some cases)", "Makes the worker buy the next hard hat always", "Tapes cracks", "Waits until an injury"], a: 0, why: "1910.132(h): replacement of employer-paid PPE. Lost or intentionally damaged items can have different policies, but work wear is on the employer." },
  { id: "pp-32", category: "ppe", topic: "Electrical gloves", q: "Rubber insulating gloves for electrical work must be:", choices: ["Rated for the voltage, inspected, and given periodic electrical testing as specified (e.g., 1910.137)", "Fashion gloves from a drugstore", "Leather only without rubber for primary protection on 4 kV", "Used past the test date"], a: 0, why: "Leather protectors over rubber. Air test each day. Class 00 through 4 voltage ratings." },
  { id: "pp-33", category: "ppe", topic: "Hearing dual", q: "Dual hearing protection (plugs plus muffs) is often required when:", choices: ["Exposures exceed 100–105 dBA in many programs / OSHA Appendix B guidance for high levels", "Noise is 70 dBA", "The worker likes the look", "Only in offices"], a: 0, why: "1910.95: when exposures equal or exceed 100 dBA some programs require dual protection; OSHA’s hearing-conservation math uses derating. Follow the standard and your program." },
  { id: "pp-34", category: "ppe", topic: "High-vis night", q: "Nighttime flaggers typically need:", choices: ["Class 3 or equivalent retroreflective garments per MUTCD", "A dark jacket", "No retroreflective material", "Only a hard hat"], a: 0, why: "1926.201 and MUTCD Part 6. Be seen or be struck." },
  { id: "pp-35", category: "ppe", topic: "Face shield plus", q: "A face shield for grinding:", choices: ["Is worn over safety glasses, not instead of them", "Replaces Z87 spectacles always", "Is optional if you squint", "Protects lungs"], a: 0, why: "Impact can come around a shield. Primary eye protection underneath." },

  { id: "el-31", category: "electrical", topic: "Qualified vs unqualified", q: "Unqualified workers may work near live parts only:", choices: ["At or beyond the approach distances in the tables — they do not perform live work", "On 480-volt bus with leather gloves", "If they have OSHA 10", "If the parts “look insulated” with paint"], a: 0, why: "1910.333 / 1926.416: training defines qualified. Paint is not insulation." },
  { id: "el-32", category: "electrical", topic: "Receptacle covers", q: "Unused openings in electrical cabinets must be:", choices: ["Effectively closed", "Left open for ventilation of breakers as a habit", "Covered with tape only in wet locations as the listed method", "Used to run extra cords without fittings"], a: 0, why: "1910.305 / 1926.405: close knockouts. Finger and tool access to live parts." },
  { id: "el-33", category: "electrical", topic: "Wet location extra-hard", q: "Flexible cords in construction wet or extra-hard usage shall be:", choices: ["Identified for extra-hard usage (e.g., types S, ST, SO, STO)", "Lamp cord (SPT-2)", "Romex as a flexible cord across the yard", "Zip cord"], a: 0, why: "1926.405(a)(2)(ii)(J): extra-hard usage. Hard usage in some dry locations." },
  { id: "el-34", category: "electrical", topic: "Overcurrent identity", q: "Each disconnect and breaker should be:", choices: ["Legibly marked to indicate its purpose unless located and arranged so the purpose is evident", "Unlabeled so only electricians know", "Marked in pencil that rubs off", "All labeled “spare”"], a: 0, why: "1910.303(f): identification. LOTO depends on knowing which breaker." },
  { id: "el-35", category: "electrical", topic: "Temp power GFCI reset", q: "If a construction GFCI trips repeatedly, the crew should:", choices: ["Find the ground fault — do not keep resetting or bypass the GFCI", "Install a cheater", "Tie the test button down", "Replace it with a non-GFCI adapter"], a: 0, why: "The trip is a warning. Wet tools and nicked cords. Fix the fault." },

  { id: "fp-46", category: "fallProtection", topic: "Low slope defined", q: "A low-slope roof is one with a slope less than or equal to:", choices: ["4 in 12 (vertical to horizontal)", "12 in 12", "1 in 12 only", "8 in 12"], a: 0, why: "1926.500: low-slope ≤ 4:12. Steep is greater than 4:12. Warning-line systems are for low-slope roofing." },
  { id: "fp-47", category: "fallProtection", topic: "Roofing low slope options", q: "On a low-slope roof 50 feet or more wide, roofers may use:", choices: ["A warning line plus guardrail, warning line plus safety net, warning line plus PFAS, or warning line plus safety monitor (with limits)", "No protection if they walk slowly", "Only a monitor with no warning line on a 200-foot-wide roof", "Body belts for arrest"], a: 0, why: "1926.501(b)(10): combinations. Roofs less than 50 feet wide may use a monitor alone as specified." },
  { id: "fp-48", category: "fallProtection", topic: "Warning line strength", q: "A warning line must be flagged at least every 6 feet and have a minimum tensile strength of:", choices: ["500 pounds", "50 pounds", "5,000 pounds", "200 pounds same as a top rail"], a: 0, why: "1926.502(f)(2): 500 lb tensile, stanchions that resist 16 lb, line 34–39 inches high." },
  { id: "fp-49", category: "fallProtection", topic: "PFAS deceleration", q: "The deceleration device on a PFAS shall bring an employee to a complete stop and limit deceleration distance to:", choices: ["3.5 feet", "6 feet", "12 feet", "30 feet"], a: 0, why: "1926.502(d)(16)(iii)–(iv): 3.5 ft deceleration distance and 1,800 lb maximum arresting force on the body with a harness." },
  { id: "fp-50", category: "fallProtection", topic: "Net drop test", q: "Safety nets must be drop-tested at the jobsite:", choices: ["After installation, relocation, and at 6-month intervals, with a 400-lb bag of sand 28–32 inches in diameter dropped from at least 42 inches above the surface", "Never", "With a person jumping in", "Only at the factory"], a: 0, why: "1926.502(c)(4): drop test or certified equivalent. Inspect nets for debris and damage." },

  { id: "ex-31", category: "excavation", topic: "Hazardous atmosphere LEL", q: "A hazardous atmosphere in an excavation includes flammable gas in excess of:", choices: ["20% of the LEL (1926.651 uses 20% LEL; confined space 1910.146 uses 10% — know which rule applies)", "100% LEL only", "1% oxygen", "The PEL for silica"], a: 0, why: "1926.651(g): >20% of LEL is a hazardous atmosphere in excavations. Permit spaces use 10% in 1910.146. Test before entry." },
  { id: "ex-32", category: "excavation", topic: "Emergency rescue", q: "Where a hazardous atmosphere could exist in an excavation, emergency rescue equipment (e.g., breathing apparatus, harness/lanyard, basket stretcher) shall be:", choices: ["Attended when used and readily available where needed", "Stored at the shop 30 minutes away", "Optional if workers can hold their breath", "Only a cell phone"], a: 0, why: "1926.651(g)(2): rescue equipment. Do not become the second victim." },
  { id: "ex-33", category: "excavation", topic: "Support system install", q: "Support systems (shoring) must be installed:", choices: ["Progressively as the excavation proceeds, from the top down, and removed from the bottom up except as allowed", "After the trench is fully open to the final depth with people in it", "Only at the ends", "Never in Type C"], a: 0, why: "1926.652(e): installation and removal. Workers stay within the protected zone." },
  { id: "ex-34", category: "excavation", topic: "Ramp slope employees", q: "A ramp used for employee access with a slope steeper than 4:1 (14 degrees) must have:", choices: ["A stairway or steps cut into the ramp and a handrail if there is a drop of 6 feet or more as specified", "No extra features", "Only a rope", "A ladder laid on the dirt always"], a: 0, why: "1926.651(c)(1)(v): steep ramps need stair treads and fall protection when the drop requires it." },
  { id: "ex-35", category: "excavation", topic: "Surface encumbrances", q: "Trees, boulders, and other surface encumbrances that create a hazard shall be:", choices: ["Removed or supported", "Ignored", "Used as spoil piles against the lip", "Pushed into the trench"], a: 0, why: "1926.651(a): surface encumbrances. They can fall into the hole or surcharge the wall." },

  { id: "ld-28", category: "ladders", topic: "3-foot exception", q: "If a portable ladder cannot extend 3 feet above the landing, you must:", choices: ["Secure the ladder and provide a grasping device such as a grabrail", "Stand on the top cap", "Have a coworker toss you a rope from above as the only control", "Lean it at 1:1"], a: 0, why: "1926.1053(b)(1): 3-foot extension or secure + grab device." },
  { id: "ld-29", category: "ladders", topic: "Double cleat", q: "A double-cleat ladder is required when:", choices: ["A ladder is the only way to enter/exit a working area with 25 or more employees, or two-way traffic is expected, as specified", "Any time two people might ever use a ladder", "Never", "Only on scaffolds"], a: 0, why: "1926.1053(a)(2): two-way traffic. 18-inch minimum width between cleats on double-cleat ladders." },
  { id: "ld-30", category: "ladders", topic: "Scaffold falling objects", q: "When workers are below a scaffold, falling-object protection includes:", choices: ["Toeboards, screens, debris nets, catch platforms, canopy structures, or barricades below", "Hard hats only with no other control", "Yelling", "Painting tools orange"], a: 0, why: "1926.451(h). Toeboards at least 3.5 inches. Barricade the area below if objects could still fall." },
  { id: "ld-31", category: "ladders", topic: "Snow ice scaffold", q: "Slippery conditions on scaffolds shall be:", choices: ["Eliminated as soon as practicable — do not work on ice-covered planks", "Ignored with extra care", "Covered with more ice", "A reason to remove guardrails"], a: 0, why: "1926.451(f)(8): snow, ice, and slippery conditions. Competent person decides." },
  { id: "ld-32", category: "ladders", topic: "Tag scaffold", q: "Many scaffold programs use green/yellow/red tags to show:", choices: ["Inspected and safe / restricted use / do not use — a competent person updates them each shift", "Paint colors", "Who owns the frames", "Wind speed only"], a: 0, why: "Not strictly mandated tag colors by OSHA, but they implement 1926.451(f)(3) inspections. Red means do not climb." },

  { id: "fr-21", category: "fire", topic: "Construction extinguishers", q: "A fire extinguisher rated not less than 2A shall be provided for each:", choices: ["3,000 square feet of protected building area, or major fraction, on a construction site (with travel distance rules)", "100 square feet always", "Entire project regardless of size, one extinguisher total always", "Office only"], a: 0, why: "1926.150(c)(1): 2A per 3,000 sq ft, travel distance 100 feet. Also 2A within 100 feet of each storey in multi-story work." },
  { id: "fr-22", category: "fire", topic: "Fuel gas construction", q: "No more than 25 gallons of flammable liquids shall be stored in a room outside of an approved storage cabinet unless:", choices: ["The building is designed for that storage under 1926.152", "You are in a hurry", "The liquids are in open buckets", "They are labeled water"], a: 0, why: "1926.152: indoor storage limits. Safety cans, cabinets, and outside storage piles have extra rules." },
  { id: "fr-23", category: "fire", topic: "Safety can", q: "A safety can is:", choices: ["An approved closed container of not more than 5 gallons with a flash-arresting screen, spring-closing lid, and spout cover", "Any gas can from a garage", "An open 5-gallon bucket", "A 55-gallon drum"], a: 0, why: "1926.155 / 1910.106 definitions. Use them for gasoline on site." },
  { id: "fr-24", category: "fire", topic: "Hot work construction", q: "When welding in the vicinity of combustible materials that cannot be moved:", choices: ["Protect them with covers and have fire watch/extinguishers as 1926.352 requires", "Weld faster", "Soak rags in solvent nearby", "Rely on the building’s future sprinklers that are not yet charged"], a: 0, why: "Same as GI hot work. Construction has more wood, paper, and foam insulation." },
  { id: "fr-25", category: "fire", topic: "Alarm construction", q: "An alarm system (telephone, siren, etc.) shall be provided on a construction site so that:", choices: ["Employees can be alerted and emergency agencies contacted", "Only the radio plays music", "Nothing if under 20 workers always", "Alarms are banned as a distraction"], a: 0, why: "1926.150(e) and 1926.35 EAP. Post the numbers." },

  { id: "hh-33", category: "health", topic: "Silica 30 days", q: "Objective data can be used in the silica standard to:", choices: ["Show that exposures will remain below the action level under the conditions described, sometimes avoiding monitoring", "Skip Table 1 controls while dry-cutting", "Ignore PELs", "Replace medical exams always"], a: 0, why: "1926.1153(d)(2): performance option with air monitoring or objective data. Table 1 is the other path." },
  { id: "hh-34", category: "health", topic: "Lead action construction", q: "The construction lead action level is:", choices: ["30 μg/m³ as an 8-hour TWA", "50 μg/m³", "10 μg/m³", "500 μg/m³"], a: 0, why: "1926.62: AL 30, PEL 50. Trigger tasks (soldering, demolition of lead, welding on steel) assume exposure until you have data." },
  { id: "hh-35", category: "health", topic: "Asbestos competent", q: "Class I and II asbestos work requires a:", choices: ["Competent person on site", "Worker with OSHA 10 only", "City mayor", "No supervision"], a: 0, why: "1926.1101(o): competent person inspections. Training is more than Outreach cards." },
  { id: "hh-36", category: "health", topic: "CO generators", q: "A gasoline generator should be:", choices: ["Outdoors, away from doors/windows/vents — never in a basement, garage, or enclosed truck", "Indoors for quiet", "In a closed room with a fan blowing at a crack", "Next to the temporary heater intake"], a: 0, why: "CO deaths after storms and on jobs. Exhaust is not “just outside” if it can drift in." },
  { id: "hh-37", category: "health", topic: "Heat new workers", q: "Most heat-related deaths occur:", choices: ["In the first few days on the job or after returning from time away — acclimatize", "After 10 years in the same heat", "Only at night", "Only in offices"], a: 0, why: "OSHA heat NEP. New workers get extra rest and water. Buddy system." },

  { id: "in-31", category: "intro", topic: "SDS records access", q: "Workers have a right to access exposure and medical records under:", choices: ["1910.1020 (often applied to construction too)", "Only HIPAA, never OSHA", "The forklift standard", "Form 300A only"], a: 0, why: "1910.1020: access within 15 days typically. Includes monitoring results and SDSs as exposure records in some cases." },
  { id: "in-32", category: "intro", topic: "False reporting", q: "Falsifying OSHA logs or lying to an inspector can lead to:", choices: ["Criminal as well as civil penalties in serious cases", "A thank-you note", "Nothing", "Only a verbal warning always"], a: 0, why: "17(g) of the Act: false statements. 11(c) for retaliation. Keep honest logs." },
  { id: "in-33", category: "intro", topic: "Walkaround pay", q: "Employee representatives on an OSHA walkaround:", choices: ["Are generally paid as they would be for work time under OSHA policy/interpretations when they participate", "Must use vacation days always", "Are banned", "Only managers may walk"], a: 0, why: "The Act contemplates employee participation. Recent OSHA walkaround rule/policy has been litigated — workers still have a right to participate." },
  { id: "in-34", category: "intro", topic: "Focus Four training", q: "OSHA 10 Construction must include:", choices: ["Specified hours on Focus Four and other mandatory topics in the Outreach Training Program guidelines", "Only videos with no discussion", "Any 10 hours of toolbox talks without authorized-trainer rules", "A test that issues a DOL card without a trainer"], a: 0, why: "Authorized trainers follow OSHA’s topic outlines. This practice app does not replace that course." },
  { id: "in-35", category: "intro", topic: "OSHA 30 vs 10", q: "OSHA 30 Construction compared with OSHA 10:", choices: ["Adds supervisory and more hazard topics (elective hours) and is 30 contact hours with an authorized trainer", "Is the same test with a different sticker", "Is a federal license to run any demolition", "Expires daily"], a: 0, why: "30-hour is still awareness, not a Competent Person card by itself. Employers still train on site-specific hazards." },

  { id: "rk-21", category: "recordkeeping", topic: "First aid list", q: "Which is medical treatment (usually recordable), not first aid?", choices: ["Using wound-closing devices such as sutures, staples, or surgical glue", "Butterfly bandages / Steri-Strips", "A cold pack", "Drinking fluids for relief of heat stress as listed first aid"], a: 0, why: "1904.7(b)(5): Steri-Strips are first aid; sutures/staples/glue are medical treatment." },
  { id: "rk-22", category: "recordkeeping", topic: "Prescription", q: "A single dose of prescription medication is:", choices: ["Medical treatment — recordable if work-related", "First aid", "Never recordable", "Only recordable if three doses"], a: 0, why: "Even one prescription dose is medical treatment under Part 1904 (with a narrow exception for some preventive meds — follow the text)." },
  { id: "rk-23", category: "recordkeeping", topic: "Loss of consciousness", q: "Work-related loss of consciousness is:", choices: ["Recordable regardless of how long it lasts", "Recordable only if over 5 minutes", "First aid", "Never recordable if they return to work"], a: 0, why: "1904.7(b)(6): any loss of consciousness." },
  { id: "rk-24", category: "recordkeeping", topic: "Restricted work", q: "Restricted work means the employee cannot:", choices: ["Perform one or more routine job functions or work a full day because of the injury, as assigned by the employer or PLHCP", "Only that they missed a favorite overtime shift by choice", "That they were given a harder job", "A vacation day"], a: 0, why: "1904.7(b)(4): restricted work / job transfer. Light duty still counts." },
  { id: "rk-25", category: "recordkeeping", topic: "Day counts", q: "When counting days away, you include:", choices: ["Calendar days, not just scheduled workdays, with a 180-day cap for recording purposes", "Only Saturdays", "Unlimited years on the log line", "Only the day of injury, never later days"], a: 0, why: "1904.7(b)(3): cap at 180 days. The day of injury is not counted as a day away." }
];
